//! End-to-end check against the checked-in showcase vault in `fixtures/vault/full`.
//!
//! The vault is generated by `scripts/gen-full-vault.py` and is meant to exercise
//! every part of the app: cash and e-wallets, two bank accounts, a credit card, a
//! mortgage and a car loan, salary/bonus, interest and dividends, a self-owned and
//! a rented flat, a car, monthly and yearly envelopes, and a handful of big
//! one-off expenses.

use std::path::{Path, PathBuf};
use std::str::FromStr;

use ledger_engine::report;
use ledger_engine::types::{AccountNodeDto, QueryRequest};
use ledger_engine::{Vault, VaultOptions};
use rust_decimal::Decimal;

fn find<'a>(nodes: &'a [AccountNodeDto], full: &str) -> Option<&'a AccountNodeDto> {
    for node in nodes {
        if node.full == full {
            return Some(node);
        }
        if let Some(hit) = find(&node.children, full) {
            return Some(hit);
        }
    }
    None
}

fn full() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/vault/full")
}

fn vault() -> Vault {
    Vault::load(&full(), &VaultOptions::default()).expect("showcase vault loads")
}

fn d(value: &str) -> Decimal {
    Decimal::from_str(value).unwrap()
}

#[test]
fn showcase_vault_loads_without_errors() {
    let vault = vault();
    let errors: Vec<String> = vault
        .diagnostics()
        .iter()
        .filter(|d| d.severity == ledger_core::Severity::Error)
        .map(|d| d.display())
        .collect();
    assert!(errors.is_empty(), "showcase vault has errors: {errors:#?}");
    assert!(
        vault.transactions().len() >= 320,
        "expected the full history"
    );
    assert!(
        vault.transactions().iter().all(|t| t.balanced),
        "every generated entry is double-entry balanced"
    );
    assert_eq!(vault.missing_fx_count(), 0, "prices.ledger covers the trip");
    assert_eq!(vault.info_dto().base_commodity, "CNY");
}

#[test]
fn balance_sheet_carries_both_properties_and_both_loans() {
    let vault = vault();
    let tree = vault.account_tree();

    let home = find(&tree, "assets:property:home").expect("self-owned flat");
    assert_eq!(home.kind, "A");
    assert_eq!(home.own[0].quantity, "1800000.00");

    let rental = find(&tree, "assets:property:rental").expect("rented flat");
    assert_eq!(rental.own[0].quantity, "900000.00");

    let car = find(&tree, "assets:vehicle:car").expect("car");
    assert_eq!(car.kind, "A");

    let mortgage = find(&tree, "liabilities:mortgage:home").expect("mortgage");
    assert_eq!(mortgage.kind, "L");
    // 1,500,000 borrowed, 16 payments of the principal part.
    assert_eq!(mortgage.own[0].quantity, "-1467360.00");

    let car_loan = find(&tree, "liabilities:loan:car").expect("car loan");
    assert_eq!(car_loan.own[0].quantity, "-107080.00");

    let card = find(&tree, "liabilities:credit:cmb").expect("credit card");
    assert_eq!(card.kind, "L");
}

#[test]
fn net_worth_equals_assets_minus_liabilities() {
    let vault = vault();
    let total: Decimal = vault.net_worth().iter().map(|a| d(&a.quantity)).sum();
    // Assets minus liabilities at the end of the history (the USD trip is
    // converted at its own @@ cost of 7.18, not at today's rate).
    let expected = d("1800000")   // home
        + d("900000")             // rental
        + d("168000")             // car
        + d("22904")              // icbc
        + d("405600")             // cmb
        + d("286630")             // emergency fund
        + d("188000")             // index fund
        + d("187840")             // stocks
        + d("4600")               // cash
        + d("4040")               // alipay
        + d("2720")               // wechat
        - d("11500")              // credit card
        - d("107080")             // car loan
        - d("1467360"); // mortgage
    assert_eq!(total, expected);
    assert!(total > d("1000000"), "the household is not underwater");
}

#[test]
fn dashboard_shows_recurring_income_and_the_big_expenses() {
    let vault = vault();
    let dashboard = report::dashboard(&vault, 12);
    assert_eq!(dashboard.kpis.month, "2026-10");
    assert!(dashboard.kpis.net_worth.value > 1_000_000.0);
    assert!(dashboard.kpis.month_income.value > 20_000.0);
    assert!(!dashboard.months.is_empty());
    assert!(!dashboard.categories.is_empty());
    assert!(!dashboard.sankey.links.is_empty());
    assert!(!dashboard.heatmap.is_empty());
    assert!(!dashboard.forecast.is_empty());

    // The showcase keeps a full year of history, so the net-worth curve rises.
    let series = &dashboard.net_worth_series;
    assert!(series.len() >= 10);
    assert!(series.last().unwrap().value > series.first().unwrap().value);

    // Renovation (96,000 + 8,300) and the appliance spree are in there.
    let renovation = report::query_txns(
        &vault,
        &QueryRequest {
            query: Some("acct:renovation".into()),
            offset: 0,
            limit: 50,
            order: None,
            date_from: None,
            date_to: None,
        },
    )
    .expect("query runs");
    assert_eq!(renovation.total, 2);
}

#[test]
fn budgets_cover_spending_and_savings_envelopes() {
    let vault = vault();
    let rows = report::dashboard(&vault, 12).budget;
    let food = rows
        .iter()
        .find(|row| row.account == "expenses:food")
        .expect("food envelope");
    assert_eq!(food.budget_display, "4,500.00 CNY");
    assert!(food.actual > 0.0);

    let emergency = rows
        .iter()
        .find(|row| row.account == "assets:savings:emergency")
        .expect("savings envelope");
    assert_eq!(emergency.kind, "A");
    assert_eq!(emergency.actual_display, "1,500.00 CNY");

    // A yearly envelope is divided by twelve for the monthly view.
    let travel = rows
        .iter()
        .find(|row| row.account == "expenses:travel")
        .expect("travel envelope");
    assert_eq!(travel.budget_display, "2,500.00 CNY");
}

#[test]
fn rules_match_the_showcase_payees() {
    let vault = vault();
    let rules = vault.rules.enabled_rules().collect::<Vec<_>>();
    assert_eq!(rules.len(), 4);
    assert!(rules.iter().any(|rule| rule.id == "r-star"));
    assert!(rules
        .iter()
        .any(|rule| rule.from_account.as_deref() == Some("assets:bank:cmb")));
}
